#!/usr/bin/env python3
"""Правка README аудита #5182 по замечаниям верификатора: SEO-TECH-352 → «не проверить»,
гипотезы kb (SEO-CONT-140/141, SEO-ONP-200, CONV-OFFER-140) → кандидаты в тест, пересчёт."""
import sys

p = sys.argv[1]
t = open(p, encoding="utf-8").read()
pairs = [
    ("**Итог.** В `findings.csv` 129 пунктов kb. Применимых проверено 102: выполнено 55, нарушено 47. Ещё 14 применимых проверить не удалось: нет данных Вебмастера и GSC, нет кабинета Яндекс Бизнеса, формы мы не отправляли. 13 пунктов к сайту не подходят.",
     "**Итог.** В `findings.csv` 129 пунктов kb. Применимых проверено 97: выполнено 55, нарушено 42. Ещё 19 применимых в статусе «не проверить». Из них 15 — без данных: в доступных нам аккаунтах Вебмастера и GSC сайта нет, кабинета Яндекс Бизнеса нет, формы мы не отправляли. Ещё 4 — гипотезы kb, которые пока проверяются (SEO-CONT-140, SEO-CONT-141, SEO-ONP-200, CONV-OFFER-140). В нарушения гипотезы не засчитаны: это кандидаты в тест с контрольной группой, отдельный раздел ниже. 13 пунктов к сайту не подходят."),
    ("1. **Поисковики сайт почти не видят, и следить за этим нечем.** ne-prosto.ru нет в Яндекс Вебмастере (API: HOST_NOT_FOUND, в аккаунте 38 хостов), нет в GSC сервисного аккаунта (23 свойства), нет карточки в SEO Monitor и проекта в Labrika. По Метрике за 14–27.11 из 628 визитов из поиска пришли 4.",
     "1. **В доступных нам кабинетах сайта нет, поэтому индексацию и запросы проверить не удалось.** ne-prosto.ru нет среди 38 хостов Вебмастера аккаунта с METRIKA_TOKEN (API: HOST_NOT_FOUND) и среди 23 свойств GSC сервисного аккаунта reports-writer, нет карточки в SEO Monitor и проекта в Labrika. Подтверждён ли сайт в каком-то другом аккаунте, неизвестно: meta-тегов подтверждения на страницах нет, но подтвердить могли через DNS или файлом. Из поиска по Метрике за 14–27.11 пришли 4 визита из 628."),
    ("| 1 | SEO-TECH-352 (открывает TAUDIT-2, SEO-TECH-015, 309, CANNIB-2) | Добавить ne-prosto.ru в Яндекс Вебмастер (аккаунт с METRIKA_TOKEN) и в GSC с доступом reports-writer. Подтвердить meta-тегом в чанке head или через DNS, отправить sitemap, связать с организацией 1075017343 в Картах, завести карточку в SEO Monitor. На доске #5259 | 3 | 1 |",
     "| 1 | KB: нет пункта (вне счётчика); после него можно проверить SEO-TECH-352, 015, 309, TAUDIT-2, CANNIB-2 | Выяснить у Антона, подтверждён ли сайт в другом кабинете. Если да — выдать доступ аккаунту с METRIKA_TOKEN и reports-writer, если нет — добавить сайт в Вебмастер и GSC и подтвердить (meta-тег в чанке head или DNS). Затем отправить sitemap, связать сайт с организацией 1075017343 в Картах и завести карточку в SEO Monitor. На доске #5259 | 3 | 1 |"),
    ("| 9 | SEO-ONP-200, TECH-2, SEO-ONP-316 | Один JSON-LD чанк: Organization и WebSite на главной и контактах, BreadcrumbList по пути, Article в шаблоне 8 (даты через strtotime, DEV-MODX-102), Service на услугах. Только то, что видно на странице | 2 | 2 |",
     "| 9 | TECH-2, SEO-ONP-316 | Один JSON-LD чанк: WebSite на главной, BreadcrumbList по пути, Article в шаблоне 8 (даты через strtotime, DEV-MODX-102), Service на услугах. Только то, что видно на странице. Organization на главной — гипотеза SEO-ONP-200 в тесте лаборатории: ставить в волне теста, а не отдельно | 2 | 2 |"),
    ("| 10 | PTYPE-1, TEXT-5, SEO-CONT-001, CONV-OFFER-140, STRUCT-1 |", "| 10 | PTYPE-1, TEXT-5, SEO-CONT-001, STRUCT-1 |"),
    (", «Коротко» и «Частые вопросы» в шаблоне автопилота (SEO-CONT-140, 141), автор и дата", ", автор и дата"),
    ("- **Description на хабах и услугах** (SEO-ONP-350) нарушен ещё на 9 сайтах. **WebSite с названием** (SEO-ONP-316) — на 9, **Organization** (SEO-ONP-200) — на 6, **структурированные данные вообще** (TECH-2) — на 6. Для MODX это один общий чанк JSON-LD.",
     "- **Description на хабах и услугах** (SEO-ONP-350) нарушен ещё на 9 сайтах. **WebSite с названием** (SEO-ONP-316) — на 9, **структурированные данные вообще** (TECH-2) — на 6. Для MODX это один общий чанк JSON-LD; Organization (SEO-ONP-200) в него не включать до вердикта теста."),
    ("- **Шаблон автопилота блога.** «Коротко» (SEO-CONT-140) нет ещё на 11 сайтах, «Частых вопросов» (SEO-CONT-141) — на 7. Правка одного промпта автопилота закрывает все блоги разом.\n",
     "- **Гипотезы — не пакет, а тест.** «Коротко» (SEO-CONT-140), «Частые вопросы» (SEO-CONT-141), Organization (SEO-ONP-200) и цена в первом экране услуги (CONV-OFFER-140) в kb ещё проверяются, раскатывать их через общий промпт автопилота до замера нельзя. Блоков нет на многих сайтах пачки, так что опытную и контрольную группы есть из кого собрать. Все 24 соседних аудита на 28.11, 11:00 МСК засчитали такие гипотезы нарушениями: SEO-CONT-140 — 21 аудит, SEO-CONT-141 — 14, SEO-ONP-200 — 11, CONV-OFFER-140 — 6. Их счётчики стоит пересчитать по тому же правилу, на доске #5262.\n"),
    ("- Индексация, исключённые страницы, запросы и позиции, внешние ссылки, санкции — без Вебмастера и GSC (SEO-TECH-309, 015, TAUDIT-2, CANNIB-2, SEO-ONP-140, SEO-OFF-301).",
     "- Индексация, исключённые страницы, запросы и позиции, внешние ссылки, санкции и контроль URL Inspection после редизайна: в доступных нам аккаунтах Вебмастера и GSC сайта нет (SEO-TECH-352, 309, 015, TAUDIT-2, CANNIB-2, SEO-ONP-140, SEO-OFF-301)."),
    ("- Вебмастер: сайта нет (HOST_NOT_FOUND). GSC: свойства нет.",
     "- Вебмастер аккаунта с METRIKA_TOKEN: сайта нет (HOST_NOT_FOUND). GSC сервисного аккаунта reports-writer: свойства нет."),
]
for a, b in pairs:
    assert a in t, "не найдено: " + a[:70]
    t = t.replace(a, b)

tests = """## Кандидаты в тест — не нарушения

Эти пункты kb — гипотезы в статусе «проверяется» или «кандидат», их эффект ещё не доказан. В CSV у них статус «не проверить», в счётчик нарушений они не входят. Массово не раскатывать: сначала тест с контрольной группой. На ne-prosto для замера мало трафика (4 поисковых визита и 3 заявки за 2 недели), поэтому тестировать на сайтах с трафиком, а ne-prosto подключать после вердикта.

| Пункт | Что на сайте | Как проверить |
|---|---|---|
| SEO-CONT-140 | Ни в одной из 30 статей нет абзаца «Коротко» под H1 | Часть новых статей автопилота с «Коротко», часть без; сравнить показы и клики из поиска за равные окна |
| SEO-CONT-141 | Блоков «Частые вопросы» в статьях нет, FAQPage нет нигде; FAQ-сниппеты Google не показывает с 7 мая 2026 | 3–4 вопроса из подсказок Яндекса и FAQPage в опытной группе статей, контрольная без блока; мерить число разных запросов с показами |
| SEO-ONP-200 | Разметки Organization нет (проба org_markup — «нет»), карточка в Картах есть: org 1075017343 | Тест лаборатории по пробе org_markup; сайт уже стоял в его очереди и ждал трафика |
| CONV-OFFER-140 | Цены нет ни на одной услуге, в первом экране /uslugi/sajtyi на 390 px нет ни цены, ни кнопки | Сначала цель на кнопку заявки, потом цена «от» и кнопка в первом экране части услуг; сравнить с услугами без правки, 21 день до и после. Сам блок цен нужен и так, по PTYPE-1 |

"""
anchor = "## Что уже хорошо"
assert anchor in t
t = t.replace(anchor, tests + anchor, 1)

kb_anchor = "- KB: ошибка | content/qa |"
kb_new = ("- KB: правило | agents/аудит | В аудите по kb гипотезы в статусе «проверяется» и «кандидат» не засчитывать нарушениями "
          "и не предлагать к массовой раскатке: в отчёт они идут кандидатами в тест с контрольной группой | #5182: верификатор вернул "
          "отчёт из-за SEO-CONT-140/141; в 24 аудитах пачки 28.11 такие гипотезы засчитаны нарушениями (SEO-CONT-140 — в 21) | audit, kb, lab\n")
assert kb_anchor in t
t = t.replace(kb_anchor, kb_new + kb_anchor, 1)
open(p, "w", encoding="utf-8").write(t)
print("ok")
